113	  public Eth1Data getEth1Vote(BeaconState state) {
114	    NavigableMap<UInt64, Eth1Data> votesToConsider =
115	        getVotesToConsider(state.getSlot(), state.getGenesisTime(), state.getEth1Data());
116	    // Avoid using .values() directly as it has O(n) lookup which gets expensive fast
117	    final Set<Eth1Data> validBlocks = new HashSet<>(votesToConsider.values());
118	    final Map<Eth1Data, Eth1Vote> votes = countVotes(state);
119	
120	    Eth1Data defaultVote =
121	        votesToConsider.isEmpty() ? state.getEth1Data() : votesToConsider.lastEntry().getValue();
122	
123	    Optional<Eth1Data> vote =
124	        votes.entrySet().stream()
125	            .filter(entry -> validBlocks.contains(entry.getKey()))
126	            .max(Map.Entry.comparingByValue())
127	            .map(Map.Entry::getKey);
128	
129	    return vote.orElse(defaultVote);
130	  }
131	
132	  public Collection<Eth1Data> getAllEth1Blocks() {
133	    return this.eth1ChainCache.values().stream().map(Eth1DataAndHeight::getEth1Data).toList();
134	  }
