23	public class AsyncRunLoop {
24	
25	  private final AtomicBoolean stopped = new AtomicBoolean(false);
26	
27	  private final RunLoopLogic logic;
28	  private final AsyncRunner asyncRunner;
29	  private final Duration retryDelay;
30	
31	  public AsyncRunLoop(
32	      final RunLoopLogic logic, final AsyncRunner asyncRunner, final Duration retryDelay) {
33	    this.logic = logic;
34	    this.asyncRunner = asyncRunner;
35	    this.retryDelay = retryDelay;
36	  }
37	
38	  public void start() {
39	    logic
40	        .init()
41	        .thenCompose(__ -> nextLoopAfterDelay())
42	        .finish(error -> onError(error, this::start));
43	  }
44	
45	  public void stop() {
46	    stopped.compareAndSet(false, true);
47	  }
48	
49	  private SafeFuture<Void> nextLoopAfterDelay() {
50	    if (stopped.get()) {
51	      return SafeFuture.COMPLETE;
52	    }
53	    return asyncRunner.runAfterDelay(
54	        () -> {
55	          if (stopped.get()) {
56	            return;
57	          }
58	          nextLoop();
59	        },
60	        logic.getDelayUntilNextAdvance());
61	  }
62	
63	  private void nextLoop() {
64	    logic
65	        .advance()
66	        .thenCompose(__ -> nextLoopAfterDelay())
67	        .finish(error -> onError(error, this::nextLoop));
68	  }
69	
70	  private void onError(final Throwable error, final ExceptionThrowingRunnable retryAction) {
71	    if (error instanceof CompletionException && error.getCause() != null) {
72	      logic.onError(error.getCause());
73	    } else {
74	      logic.onError(error);
75	    }
76	    asyncRunner.runAfterDelay(retryAction, retryDelay).ifExceptionGetsHereRaiseABug();
77	  }
78	}
